SELECT s.*, c.name AS category_name
FROM t_spu s LEFT JOIN t_category c ON s.category_id = c.id


        AND s.id = #{id}


        AND s.name LIKE CONCAT('%', #{name}, '%')


        AND s.category_id = #{categoryId}


        AND s.status = #{status}


ORDER BY s.id DESC

